"""Causal synthetic weather for Indang, Cavite.

Design (why the ML has something real to learn):
  * Rain is generated by *weather systems* (convective cells, Habagat bands, and
    dissipating "decoy" systems). Each system has an APPROACH phase (precursors:
    pressure fall, humidity rise, cloud build-up, light drop, outflow cooling)
    that starts BEFORE rain onset, then a rain phase, then a decay phase.
  * Precursor strength is correlated with, but does not determine, whether it
    rains (some strong-looking systems fizzle, some weak ones rain). Nuisance
    variation (pressure tide, synoptic drift, sensor noise) hides the signal.
    So a good model can reach useful skill but never perfect skill.
  * Timestamps are local standard time; solar time is derived from longitude
    relative to the time-zone meridian (fixes the old +lon/15 shift that put
    the sun at ~4 AM).
  * The rain plate has a dry-off delay (stays "wet" a few minutes after rain).
"""
from __future__ import annotations

import math
import random
from dataclasses import dataclass
from datetime import datetime, timedelta

import numpy as np

MONTH_RAIN = [29.6, 18.0, 20.3, 34.9, 172.0, 252.5, 427.2, 432.6, 365.5, 223.0, 158.5, 98.4]
MONTH_TEMP = [24.6, 25.1, 26.3, 27.5, 27.3, 26.4, 25.6, 25.6, 25.7, 25.8, 25.6, 24.9]
SEASONS = {1: "dry", 2: "dry", 3: "dry", 4: "dry", 5: "transition", 6: "wet", 7: "wet",
           8: "wet", 9: "wet", 10: "wet", 11: "latewet", 12: "latewet"}
SCENARIOS = ["natural", "sunny", "cloud_build", "shower", "thunderstorm", "habagat",
             "false_warning", "cool_evening", "rain_now"]

CLEAR_SKY_LUX = 85000.0
DRYOFF_MIN = 3          # rain plate stays wet this many minutes after last drop
DECAY_MIN = 35          # system effects fade over this many minutes after rain ends
TIDE_AMP_HPA = 1.0      # semidiurnal atmospheric tide (peaks ~10:00 and ~22:00)


def solar_offset_hours(longitude: float) -> float:
    """Local solar time minus local clock time, for a clock on the nearest 15-degree meridian."""
    return (longitude - 15.0 * round(longitude / 15.0)) / 15.0


def daylight_fraction(solar_hour: float) -> float:
    if 6.0 <= solar_hour <= 18.0:
        return max(0.0, math.sin(math.pi * (solar_hour - 6.0) / 12.0))
    return 0.0


def month_wetness(month: int, latitude: float, longitude: float) -> float:
    """0..1 wetness. Philippine boxes use the Indang monthly table; elsewhere a broad heuristic."""
    if 4 <= latitude <= 21 and 116 <= longitude <= 127:
        return min(1.0, MONTH_RAIN[month - 1] / 432.0)
    north = latitude >= 0
    if abs(latitude) < 23.5:
        wet = month in range(5, 11) if north else (month >= 11 or month <= 4)
        return 0.8 if wet else 0.22
    wet = month in (5, 6, 7, 8, 9) if north else month in (11, 12, 1, 2, 3)
    return 0.48 if wet else 0.32


@dataclass
class WeatherState:
    timestamp: datetime
    pressure_hpa: float
    temperature_c: float
    humidity_pct: float
    light_lux: float
    rain_mm: float
    raining: bool          # rain-plate wet state (includes dry-off delay)
    scenario: str


class _System:
    """A cloud/rain system. n0 = first precursor minute, onset = n0 + lead."""
    __slots__ = ("kind", "n0", "lead", "dur", "strength", "rains", "amp_p", "amp_h", "outflow",
                 "bump", "intensity", "force_wet_until")

    def __init__(self, kind, n0, lead, dur, strength, rains, amp_p, amp_h, outflow, bump, intensity):
        self.kind, self.n0, self.lead, self.dur = kind, n0, lead, dur
        self.strength, self.rains = strength, rains
        self.amp_p, self.amp_h, self.outflow, self.bump, self.intensity = amp_p, amp_h, outflow, bump, intensity
        self.force_wet_until = -1

    @property
    def onset(self):
        return self.n0 + self.lead

    def envelope(self, n):
        tau = n - self.onset
        if tau < -self.lead:
            return 0.0
        if tau < 0:
            r = (tau + self.lead) / max(1, self.lead)
            return r ** 1.4                      # slow start, steeper near onset
        if tau < self.dur:
            return 1.0
        if tau < self.dur + DECAY_MIN:
            return 1.0 - (tau - self.dur) / DECAY_MIN
        return 0.0

    def finished(self, n):
        return n - self.onset >= self.dur + DECAY_MIN


class SyntheticWeather:
    def __init__(self, seed=42, scenario="natural", start=None, latitude=14.1953, longitude=120.8769):
        self.rng = random.Random(seed)
        self.np_rng = np.random.default_rng(seed)
        self.latitude, self.longitude = float(latitude), float(longitude)
        self.solar_off = solar_offset_hours(self.longitude)
        self.t = start or datetime.now().replace(second=0, microsecond=0)
        self.n = 0
        self.systems: list[_System] = []
        self.suppress = False
        # latent / slow state
        self.synoptic = self.rng.gauss(0, 0.8)          # slow pressure anomaly (hPa)
        self.hum_anom = self.rng.gauss(0, 3.0)
        self.temp_anom = self.rng.gauss(0, 0.3)
        self.cloud_bg = 0.25
        self.sys_p = 0.0      # low-passed system effects
        self.sys_cloud = 0.0
        self.sys_h = 0.0
        self.sys_t = 0.0
        self.temp = None
        self.wet_timer = 0
        self.scenario = "natural"
        self.set_scenario(scenario)

    # ------------------------------------------------------------------ systems
    def _new_system(self, kind, lead=None, strength=None, rains=None, dur=None, n0=None):
        r = self.rng
        s = strength if strength is not None else min(1.0, max(0.0, r.betavariate(2.0, 2.2)))
        if rains is None:
            fizzles = r.random() < 0.15                 # dissipating cell: looks scary, no rain
            rains = (not fizzles) and (s + r.gauss(0, 0.12) > 0.42)
        if kind == "convective":
            lead = lead if lead is not None else r.randint(35, 100)
            dur = dur if dur is not None else r.randint(12, 65)
            amp_p = (0.7 + 2.2 * s) * r.lognormvariate(0, 0.25)
            amp_h = (6 + 16 * s) * r.lognormvariate(0, 0.25)
            outflow = (0.8 + 3.2 * s) * r.lognormvariate(0, 0.3)
            bump = (0.3 + 1.1 * s) if rains else 0.0
            intensity = 0.5 + 2.5 * s
        else:  # "frontal" (Habagat / trough band): longer approach, longer rain, no cold pool
            lead = lead if lead is not None else r.randint(80, 200)
            dur = dur if dur is not None else r.randint(90, 380)
            amp_p = (1.2 + 2.6 * s) * r.lognormvariate(0, 0.25)
            amp_h = (8 + 14 * s) * r.lognormvariate(0, 0.25)
            outflow, bump = 0.0, 0.0
            intensity = 0.3 + 1.2 * s
        n0 = self.n if n0 is None else n0
        sysm = _System(kind, n0, lead, dur, s, rains, amp_p, amp_h, outflow, bump, intensity)
        self.systems.append(sysm)
        return sysm

    def _arrival_rate_per_min(self):
        month, hour = self.t.month, self.t.hour + self.t.minute / 60
        w = month_wetness(month, self.latitude, self.longitude)
        per_day = 0.05 + 4.0 * w ** 0.85
        diurnal = 0.35 + 1.9 * math.exp(-0.5 * ((hour - 15.5) / 3.2) ** 2)   # afternoon convection
        return per_day / 1440.0 * diurnal, w

    def set_scenario(self, scenario: str):
        if scenario not in SCENARIOS:
            scenario = "natural"
        self.scenario = scenario
        self.suppress = scenario in ("sunny", "cool_evening")
        # end anything already in progress, drop anything not yet started
        keep = []
        for s in self.systems:
            if self.n >= s.onset and scenario != "natural":
                s.dur = min(s.dur, self.n - s.onset)
                keep.append(s)
            elif scenario == "natural":
                keep.append(s)
        self.systems = keep
        if scenario == "cloud_build":
            self._new_system("convective", lead=60, strength=0.55, dur=30)
        elif scenario == "shower":
            self._new_system("convective", lead=45, strength=0.55, rains=True, dur=28)
        elif scenario == "thunderstorm":
            self._new_system("convective", lead=55, strength=0.95, rains=True, dur=55)
        elif scenario == "habagat":
            self._new_system("frontal", lead=120, strength=0.75, rains=True, dur=300)
        elif scenario == "false_warning":
            self._new_system("convective", lead=55, strength=0.7, rains=False, dur=40)
        elif scenario == "rain_now":
            s = self._new_system("convective", lead=0, strength=0.7, rains=True, dur=45)
            s.force_wet_until = self.n + 10
            self.sys_p, self.sys_cloud, self.sys_h = -s.amp_p, 0.9, s.amp_h   # already under the system

    # --------------------------------------------------------------------- step
    def step(self) -> WeatherState:
        self.t += timedelta(minutes=1)
        self.n += 1
        n, r = self.n, self.rng
        hour = self.t.hour + self.t.minute / 60
        solar_hour = (hour + self.solar_off) % 24
        month = self.t.month

        # random arrivals (natural climate); suppressed in sunny / cool_evening presets
        if not self.suppress:
            rate, w = self._arrival_rate_per_min()
            if r.random() < rate:
                frontal_p = 0.30 if w > 0.55 else 0.08
                self._new_system("frontal" if r.random() < frontal_p else "convective")
        else:
            w = month_wetness(month, self.latitude, self.longitude)

        # aggregate system effects (targets), then low-pass them so nothing jumps
        tgt_p = tgt_cloud = tgt_h = tgt_t = 0.0
        rain_i = 0.0
        forced = False
        for s in self.systems:
            e = s.envelope(n)
            if e <= 0.0:
                continue
            tau = n - s.onset
            tgt_p -= s.amp_p * e
            tgt_cloud = max(tgt_cloud, (0.35 + 0.6 * s.strength) * e ** 0.8)
            tgt_h += s.amp_h * e
            if s.outflow and tau > -14:
                ramp = min(1.0, (tau + 14) / 14.0)
                tgt_t -= s.outflow * ramp * (e if tau >= 0 else 1.0)
            if s.bump and 0 <= tau < 25:
                tgt_p += s.bump * math.exp(-tau / 7.0)          # gust-front pressure jump
            if s.rains and 0 <= tau < s.dur:
                rain_i = max(rain_i, s.intensity)
            if s.force_wet_until >= n:
                forced = True
        self.systems = [s for s in self.systems if not s.finished(n)]
        self.sys_p += (tgt_p - self.sys_p) * 0.12
        self.sys_cloud += (tgt_cloud - self.sys_cloud) * 0.10
        self.sys_h += (tgt_h - self.sys_h) * 0.10
        self.sys_t += (tgt_t - self.sys_t) * 0.15

        # slow background processes
        self.synoptic += -self.synoptic / 720.0 + r.gauss(0, 0.05)
        self.hum_anom += -self.hum_anom / 240.0 + r.gauss(0, 0.30)
        self.temp_anom += -self.temp_anom / 180.0 + r.gauss(0, 0.05)
        cloud_base = 0.12 + 0.30 * w
        self.cloud_bg += (cloud_base - self.cloud_bg) * 0.02 + r.gauss(0, 0.012)
        self.cloud_bg = min(0.7, max(0.0, self.cloud_bg))
        cloud = min(1.0, max(self.cloud_bg, self.sys_cloud))

        # rain amount / plate wetness
        rain_mm = 0.0
        if rain_i > 0 or forced:
            p_drop = 0.93 if forced else min(0.95, 0.45 + 0.30 * rain_i)
            if r.random() < p_drop:
                rain_mm = float(self.np_rng.gamma(1.6, 0.05 * max(0.6, rain_i)))
        if rain_mm > 0.02:
            self.wet_timer = DRYOFF_MIN
        elif self.wet_timer > 0:
            self.wet_timer -= 1
        raining = self.wet_timer > 0

        # ---- observables
        tide = TIDE_AMP_HPA * math.cos(2 * math.pi * (hour - 10) / 12.0)
        pressure = 1009.5 + tide + self.synoptic + self.sys_p + r.gauss(0, 0.05)

        humidity_base = 64 + 12 * w + 22 * cloud + self.hum_anom
        humidity = humidity_base + 0.55 * self.sys_h + (6 if raining else 0) + r.gauss(0, 0.7)
        humidity = min(99.0, max(45.0, humidity))

        if 4 <= self.latitude <= 21 and 116 <= self.longitude <= 127:
            seasonal = MONTH_TEMP[month - 1] + 1.8
        else:
            lat_abs = min(66.0, abs(self.latitude))
            seasonal = 29.0 - 0.11 * lat_abs + 5.0 * math.cos(
                2 * math.pi * (month - (7 if self.latitude >= 0 else 1)) / 12) * (lat_abs / 45.0)
        diurnal = 3.0 * math.sin(2 * math.pi * (solar_hour - 8) / 24)
        t_target = seasonal + diurnal + self.temp_anom - 2.0 * cloud + self.sys_t - (1.2 if raining else 0.0)
        if self.scenario == "cool_evening":
            t_target -= 2.0
        self.temp = t_target if self.temp is None else self.temp + (t_target - self.temp) * 0.25
        temperature = self.temp + r.gauss(0, 0.10)

        clear = CLEAR_SKY_LUX * daylight_fraction(solar_hour)
        light = clear * (1 - 0.85 * cloud) * (1 + r.gauss(0, 0.04)) + (r.gauss(0, 150) if clear > 0 else 0)
        light = max(0.0, min(100000.0, light))

        return WeatherState(self.t, round(pressure, 2), round(temperature, 2), round(humidity, 1),
                            round(light), round(rain_mm, 2), raining, self.scenario)
